// Sound chip engines for pack music that is generated by emulating the original game's sound hardware.
// Shared by the AudioWorklet (src/audio/worklet.ts) and the ScriptProcessor fallback (src/audio/chipplayer.ts).
import { GbMusic } from './gb/music';
import { findDseq, unpackSoundRom } from './gb/games';
import { SpcMusic, loadSong } from './snes/games';

export type ChipKind = 'gb' | 'spc';

export interface ChipEngine {
  /** fill `frames` interleaved stereo frames */
  render(dst: Float32Array, frames: number): void;
}

/** build an engine for asset `data` (format given by `kind`) playing `song` */
export function createEngine(kind: ChipKind, data: Uint8Array, song: number, sampleRate: number): ChipEngine {
  if (kind === 'gb') {
    const rom = unpackSoundRom(data);
    const drv = findDseq(rom);
    if (!drv) throw new Error('no sound driver found');
    const m = new GbMusic(rom, drv, sampleRate);
    m.start(song);
    return m;
  }
  if (kind === 'spc') {
    const spc = loadSong(data, song);
    if (!spc) throw new Error('song not in the sound snapshot');
    return new SpcMusic(spc, sampleRate);
  }
  throw new Error('unknown sound chip ' + kind);
}
